<script setup lang="ts">
import {computed,ref} from 'vue';import {useRouter,useRoute} from 'vue-router';import {useAuth} from '../stores/auth';import {api,csrf,errorText} from '../api';import {isDemo,DEMO_ACCOUNTS,DEMO_PASSWORD} from '../demo';
import {ArrowRight,Check} from 'lucide-vue-next';
const disconnected=!isDemo&&import.meta.env.VITE_STANDALONE==='true'&&import.meta.env.VITE_BACKEND_CONFIGURED!=='true';
const router=useRouter(),route=useRoute(),auth=useAuth();const email=ref(isDemo?DEMO_ACCOUNTS[0].email:''),password=ref(isDemo?DEMO_PASSWORD:''),confirmation=ref(''),busy=ref(false),error=ref(''),message=ref('');const mode=computed(()=>route.path.startsWith('/reset-password/')?'reset':route.path==='/forgot-password'?'forgot':'login');
async function quickLogin(emailValue:string){email.value=emailValue;password.value=DEMO_PASSWORD;await submit();}
async function submit(){busy.value=true;error.value='';message.value='';try{if(mode.value==='login'){await auth.login(email.value,password.value);router.push('/');}else{await csrf();const endpoint=mode.value==='forgot'?'/forgot-password':'/reset-password';message.value=(await api.post(endpoint,{email:email.value,password:password.value,password_confirmation:confirmation.value,token:route.params.token})).data.message;}}catch(e){error.value=errorText(e);}finally{busy.value=false;}}
</script>
<template><div class="login-shell"><section class="login-story"><div class="brand">express<span>conta</span><b>.</b></div><div><span class="eyebrow">MENOS SEGUIMIENTO. MÁS CONTROL.</span><h1>Tu estudio,<br>en orden.</h1><p>Empresas, antecedentes y trabajo mensual.<br>Todo conectado, de principio a fin.</p><div class="login-check" v-for="text in ['Cada pendiente tiene un responsable','Cada documento conserva su historial','Cada cliente sabe cómo avanzar']" :key="text"><Check :size="17"/>{{text}}</div></div><small>Diseñado para la forma en que trabaja tu estudio.</small></section><section class="login-form"><span class="eyebrow">BIENVENIDO A EXPRESSCONTA</span><h2>{{isDemo?'Prueba ExpressConta.':mode==='login'?'Un nuevo día, todo claro.':mode==='forgot'?'Recupera tu acceso.':'Crea una nueva contraseña.'}}</h2><p>{{isDemo?'Elige un perfil y explora el estudio con datos ficticios.':mode==='login'?'Ingresa a tu espacio de trabajo.':'Usa el correo asociado a tu cuenta.'}}</p><div v-if="isDemo" class="demo-access"><div class="demo-disclosure"><strong>Demostración · No ingreses datos reales</strong><p>Los cambios quedan solo en este navegador. No se envían correos ni se realizan cobros.</p></div><article class="demo-account" v-for="account in DEMO_ACCOUNTS" :key="account.role"><div class="demo-account-heading"><strong>{{account.label}}</strong><span>{{account.name}}</span></div><dl><div><dt>Correo</dt><dd>{{account.email}}</dd></div><div><dt>Contraseña</dt><dd>{{DEMO_PASSWORD}}</dd></div></dl><button class="button primary full" :disabled="busy" @click="quickLogin(account.email)">Entrar como {{account.label.toLowerCase()}} <ArrowRight :size="16"/></button></article><p v-if="error" class="error" role="alert">{{error}}</p></div><p v-if="disconnected" class="setup-notice" role="status">El estudio todavía no está conectado. El administrador debe habilitar el servicio para comenzar.</p><form v-else-if="!isDemo" @submit.prevent="submit"><label>Correo electrónico<input v-model="email" type="email" autocomplete="username" required placeholder="nombre@estudio.cl"></label><label v-if="mode!=='forgot'">Contraseña<input v-model="password" type="password" :autocomplete="mode==='login'?'current-password':'new-password'" :minlength="mode==='reset'?12:1" required></label><label v-if="mode==='reset'">Confirmar contraseña<input v-model="confirmation" type="password" autocomplete="new-password" minlength="12" required></label><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="message" class="success" role="status">{{message}}</p><button class="button primary full" :disabled="busy">{{busy?'Procesando…':mode==='login'?'Entrar al estudio':mode==='forgot'?'Solicitar enlace':'Actualizar contraseña'}}<ArrowRight :size="16"/></button></form><RouterLink v-if="!disconnected&&!isDemo" class="text-link" :to="mode==='login'?'/forgot-password':'/login'">{{mode==='login'?'Olvidé mi contraseña':'Volver al ingreso'}}</RouterLink><small class="login-security">{{isDemo?'Credenciales públicas de prueba. Puedes cambiar de perfil dentro de la demo.':'Acceso privado para tu estudio y sus clientes.'}}</small></section></div></template>
